sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    //Custody Trade Task and Trade task clean up
    var custodyCount1 = 0;
    var custodyTC = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
    custodyTC.addEncodedQuery('trade_idLIKEATF');
    custodyTC.query();

    while (custodyTC.next()) {
        var custodyTCN = custodyTC.sys_id;
        var custodyTT = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        custodyTT.addQuery('trade_case_id', '=', custodyTCN);
        //tt.addEncodedQuery('parent=tcn');
        custodyTT.deleteMultiple();
        custodyTC.deleteRecord();
        custodyCount1 = custodyCount1 + 1;


    }

    //Custody Trade and Ondemanding staging table cleanup
    var custCount = 0;
    var custodyTR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
    custodyTR.addEncodedQuery('trade_idLIKEATF');
    custodyTR.query();
    while (custodyTR.next()) {
         var tRID = custodyTR.sys_id;
         var onDemandRecord = new GlideRecord('x_hsb11_mss_custod_mss_custody_unity_ondemand_staging');
         onDemandRecord.addQuery('trade_id', '=', tRID);
         onDemandRecord.deleteMultiple();
        // gs.info("trade sysi id" + custodyTR.trade_id);
        custCount = custCount + 1;
    }
	custodyTR.deleteMultiple();

    //Custody Business process Instance cleanup
    var custodyBPI = new GlideRecord('x_hsb11_mss_custod_mss_custody_business_process_instance');
    custodyBPI.addEncodedQuery('object_idLIKEATF');
    custodyBPI.query();
    custodyBPI.deleteMultiple();

    var custodyBPIOne = new GlideRecord('x_hsb11_mss_custod_mss_custody_business_process_instance');
    custodyBPIOne.addEncodedQuery('recent_technical_uuidLIKEATF');
    custodyBPIOne.query();
    custodyBPIOne.deleteMultiple();


    //Event ibound set to ignored for the processing ones.
    //Ignored

    var custodyEvinb = new GlideRecord('x_hsb11_mss_custod_mss_custody_event_inbound_staging');
    custodyEvinb.addEncodedQuery('object_idLIKEATF^processing_statusINProcessing');
    custodyEvinb.query();
    //while(evinb.next())
    {
        custodyEvinb.processing_status = 'Ignored';
        custodyEvinb.updateMultiple();
    }

    // Custody Event inbound staging clean up
    var custodyEvinb1 = new GlideRecord('x_hsb11_mss_custod_mss_custody_event_inbound_staging');
    custodyEvinb1.addEncodedQuery('object_idLIKEATF');
    custodyEvinb1.query();
    custodyEvinb1.deleteMultiple();


    var custodyEvinb2 = new GlideRecord('x_hsb11_mss_custod_mss_custody_event_inbound_staging');
    custodyEvinb2.addEncodedQuery('technical_uuidLIKEATF');
    custodyEvinb2.query();
    custodyEvinb2.deleteMultiple();

})(current, previous);
